                    "sql": "CREATE OR REPLACE TABLE snitch_db_wooqer AS ( SELECT a.*, b.store_count, c.AM, c.RM, c.CITY, c.state, c.REGION, c.partner, c.\"BRANCH CODE\", am_count.AM_store_count, rm_count.RM_store_count FROM ( SELECT a.*, CASE WHEN a.store = \'NEW BEL ROAD BANGALORE\' THEN \'SNITCH - COCO - BEL ROAD\' WHEN a.store = \'BHARTIYA CITY\' THEN \'SNITCH - COCO - BHARTIYA CITY\' WHEN a.store = \'ESPLANADE MALL\' THEN \'SNITCH - COCO - ESPLANADE MALL\' WHEN a.store = \'HILITE\' THEN \'SNITCH - COCO - HILITE\' WHEN a.store = \'HSR LAYOUT BANGALORE\' THEN \'SNITCH - COCO - HSR LAYOUT\' WHEN a.store = \'JAYANAGAR BANGALORE\' THEN \'SNITCH - COCO - JAYANAGAR\' WHEN a.store = \'MantriAvenue\' THEN \'SNITCH - COCO - KORMANGLA\' WHEN a.store = \'Lulu Mall\' THEN \'SNITCH - COCO - LULU MALL\' WHEN a.store = \'AMANORA\' THEN \'SNITCH - COFO - AMANORA\' WHEN a.store = \'BANER PUNE\' THEN \'SNITCH - COFO - BANER\' WHEN a.store = \'BRIGADE ROAD BANGALORE\' THEN \'SNITCH - COFO - BRIGADE ROAD\' WHEN a.store = \'CITY CENTER\' THEN \'SNITCH - COFO - CC MANGALORE\' WHEN a.store = \'INFINITI ANDHERI\' THEN \'SNITCH - COFO - INFINITI ANDHERI\' WHEN a.store = \'INFINITI MALAD\' THEN \'SNITCH - COFO - INFINITI MALAD\' WHEN a.store = \'INFINITY VASHI\' THEN \'SNITCH - COFO - INORBIT VASHI\' WHEN a.store = \'KUKATPALLY\' THEN \'SNITCH - COFO - KUKATPALLY\' WHEN a.store = \'BANDRA\' THEN \'SNITCH - COFO - LINKING ROAD\' WHEN a.store = \'Kalyan Metro\' THEN \'SNITCH - COFO - METRO MALL\' WHEN a.store = \'RAJPUR ROAD DEHRADUN\' THEN \'SNITCH - COFO - RAJPURA ROAD\' WHEN a.store = \'SARATH CITY\' THEN \'SNITCH - COFO - SARATH CITY\' WHEN a.store = \'TRIBECA\' THEN \'SNITCH - COFO - TRIBECA\' WHEN a.store = \'VIP ROAD VIZAG\' THEN \'SNITCH - COFO - VIZAG\' WHEN a.store = \'C ROAD JODHPUR\' THEN \'SNITCH - FOCO - C ROAD JODHPUR\' WHEN a.store = \'DB MALL BHOPAL\' THEN \'SNITCH - FOCO - DB MALL\' WHEN a.store = \'EARTH EUPHORIA\' THEN \'SNITCH - FOCO - EARTH EUPHORIA\' WHEN a.store = \'EVA VADODARA\' THEN \'SNITCH - FOCO - EVA\' WHEN a.store = \'LANDMARK GANDHI NAGAR\' THEN \'SNITCH - FOCO - GANDHI NAGAR\' WHEN a.store = \'MBH VARACHHA SURAT\' THEN \'SNITCH - FOCO - MBH\' WHEN a.store = \'PMC CITADEL\' THEN \'SNITCH - FOCO - PHEONIX CITADEL\' WHEN a.store = \'SHYAMAL\' THEN \'SNITCH - FOCO - SHYAMAL\' WHEN a.store = \'TRION VADODARA\' THEN \'SNITCH - FOCO - TRION\' WHEN a.store = \'VAISHALI NAGAR JAIPUR\' THEN \'SNITCH - FOCO - VAISHALI NAGAR\' WHEN a.store = \'VR MALL SURAT\' THEN \'SNITCH - FOCO - VR MALL\' WHEN a.store = \'YAGNIK\' THEN \'SNITCH - FOCO - YAGNIK\' WHEN a.store = \'Hubli\' THEN \'Mapping Pending\' WHEN a.store = \'Kothapet\' THEN \'Mapping Pending\' WHEN a.store = \'Lajpat Nagar\' THEN \'Mapping Pending\' WHEN a.store = \'Phoenix Palassio\' THEN \'Mapping Pending\' WHEN a.store = \'Rajahmundry\' THEN \'Mapping Pending\' ELSE \'Unknown Store\' END AS store_name_mapping FROM snitch_db1_wooqer a ) a LEFT JOIN ( SELECT EXTRACT(WEEK FROM TO_DATE(\"Date (dd/mm/yyyy)\", \'DD-MM-YYYY\')) AS week_number, COUNT(DISTINCT store) AS store_count FROM snitch_db1_wooqer GROUP BY EXTRACT(WEEK FROM TO_DATE(\"Date (dd/mm/yyyy)\", \'DD-MM-YYYY\')) ) b ON EXTRACT(WEEK FROM TO_DATE(a.\"Date (dd/mm/yyyy)\", \'DD-MM-YYYY\')) = b.week_number LEFT JOIN snitch_db.maplemonk.master_offine c ON a.store_name_mapping = c.\"FROM BRANCH NAME\" LEFT JOIN ( SELECT AM, COUNT(DISTINCT \"FROM BRANCH NAME\") AS AM_store_count FROM snitch_db.maplemonk.master_offine GROUP BY AM ) am_count ON c.AM = am_count.AM LEFT JOIN ( SELECT \"RM\", COUNT(DISTINCT \"FROM BRANCH NAME\") AS RM_store_count FROM snitch_db.maplemonk.master_offine GROUP BY \"RM\" ) rm_count ON c.RM = rm_count.RM); CREATE OR REPLACE TABLE snitch_db_wooqer3 AS ( WITH store_list AS ( SELECT \'CITY CENTER\' AS Store UNION ALL SELECT \'JAYANAGAR BANGALORE\' UNION ALL SELECT \'EVA VADODARA\' UNION ALL SELECT \'HSR LAYOUT BANGALORE\' UNION ALL SELECT \'VIP ROAD VIZAG\' UNION ALL SELECT \'EARTH EUPHORIA\' UNION ALL SELECT \'INFINITI ANDHERI\' UNION ALL SELECT \'INFINITY VASHI\' UNION ALL SELECT \'MantriAvenue\' UNION ALL SELECT \'NEW BEL ROAD BANGALORE\' UNION ALL SELECT \'PMC CITADEL\' UNION ALL SELECT \'RAJPUR ROAD DEHRADUN\' UNION ALL SELECT \'SARATH CITY\' UNION ALL SELECT \'SHYAMAL\' UNION ALL SELECT \'TRIBECA\' UNION ALL SELECT \'TRION VADODARA\' UNION ALL SELECT \'VR MALL SURAT\' UNION ALL SELECT \'YAGNIK\' UNION ALL SELECT \'BANDRA\' UNION ALL SELECT \'BRIGADE ROAD BANGALORE\' UNION ALL SELECT \'HILITE\' UNION ALL SELECT \'INFINITI MALAD\' UNION ALL SELECT \'KUKATPALLY\' UNION ALL SELECT \'LANDMARK GANDHI NAGAR\' UNION ALL SELECT \'AMANORA\' UNION ALL SELECT \'DB MALL BHOPAL\' UNION ALL SELECT \'BANER PUNE\' UNION ALL SELECT \'MBH VARACHHA SURAT\' UNION ALL SELECT \'VAISHALI NAGAR JAIPUR\' UNION ALL SELECT \'C ROAD JODHPUR\' UNION ALL SELECT \'BHARTIYA CITY\' UNION ALL SELECT \'ESPLANADE MALL\' UNION ALL SELECT \'Hubli\' UNION ALL SELECT \'Kalyan Metro\' UNION ALL SELECT \'Kothapet\' UNION ALL SELECT \'Lajpat Nagar\' UNION ALL SELECT \'Lulu Mall\' UNION ALL SELECT \'Phoenix Palassio\' UNION ALL SELECT \'Rajahmundry\' ), process_list AS ( SELECT \'Opening Checklist\' AS Process UNION ALL SELECT \'Closing Checklist\' UNION ALL SELECT \'DSP\' UNION ALL SELECT \'Grooming-1st Shift\' UNION ALL SELECT \'Grooming-2nd Shift\' UNION ALL SELECT \'HK Grooming Picture-1st Shift\' UNION ALL SELECT \'Cash Deposit\' UNION ALL SELECT \'HK Grooming Picture-2nd Shift\' ), date_list AS ( SELECT DISTINCT \"Date (dd/mm/yyyy)\" FROM snitch_db1_wooqer ), all_combinations AS ( SELECT d.\"Date (dd/mm/yyyy)\", s.Store, p.Process FROM date_list d CROSS JOIN store_list s CROSS JOIN process_list p ), full_entries AS ( SELECT ac.\"Date (dd/mm/yyyy)\", ac.Store, ac.Process, CASE WHEN wd.Store IS NOT NULL THEN \'Completed\' ELSE \'Missed\' END AS Status FROM all_combinations ac LEFT JOIN snitch_db1_wooqer wd ON ac.\"Date (dd/mm/yyyy)\" = wd.\"Date (dd/mm/yyyy)\" AND ac.Store = wd.Store AND ac.Process = wd.Process ) SELECT \"Date (dd/mm/yyyy)\", Store, LISTAGG(CASE WHEN Status = \'Completed\' THEN Process END, \', \') AS \"Completed Process\", LISTAGG(CASE WHEN Status = \'Missed\' THEN Process END, \', \') AS \"Missed Process\" FROM full_entries GROUP BY \"Date (dd/mm/yyyy)\", Store)",
